\operatorname{Sub}_{\mathsf U}:
(\mathsf{Ty}_{\mathsf U}\cup\mathsf{Tm}_{\mathsf U})\times\mathsf{Var}_{\mathsf U}\times\mathsf{Tm}_{\mathsf U}
\to\mathsf{Ty}_{\mathsf U}\cup\mathsf{Tm}_{\mathsf U}

\frac{\Gamma\vdash A:\mathsf U_i\quad\Gamma\vdash B:\mathsf U_i\quad
\Gamma\vdash e:\operatorname{Equiv}(A,B)}
{\Gamma\vdash\operatorname{ua}(e):\operatorname{Id}_{\mathsf U_i}(A,B)}.

\mathsf{CompEqJud}_{\mathsf U}
=\{\Gamma\vdash t\equiv u:A:\Gamma\in\mathsf{Ctx}_{\mathsf U},\
t,u\in\mathsf{Tm}_{\mathsf U},\ A\in\mathsf{Ty}_{\mathsf U}\}
\subseteq\mathsf{Jud}_{\mathsf U}.

\mathsf{MainJud}_{\mathsf U}
=
\{\Gamma\vdash t:A:t\in\mathsf{Tm}_{\mathsf U},A\in\mathsf{Ty}_{\mathsf U}\}
\cup
\{\Gamma\vdash A:\mathsf U_i:A\in\mathsf{Ty}_{\mathsf U},i\in\mathbb N\}
\cup\mathsf{CompEqJud}_{\mathsf U}.

\mathsf{Der}_{\mathsf U}
=\{(D,\ell):D\in\mathsf{TreeDom}_{\mathsf U},\ \ell:D\to\mathsf{Jud}_{\mathsf U},\
\forall p\in D\ ((\ell(p^\frown0),\ldots,\ell(p^\frown(k_p-1))),\ell(p))\in\mathsf{Rule}_{\mathsf U}\}.

\mathsf{AxJdg}_{\mathsf U}
=
\{\Gamma\vdash\mathsf U_i:\mathsf U_{i+1}:i\in\mathbb N\}
\cup
\{\Gamma\vdash x:A:x:A\in\Gamma\}
\cup
\{\Gamma\vdash\operatorname{refl}(a):\operatorname{Id}_A(a,a):\Gamma\vdash a:A\}.
